import{F as e,M as t,_ as n,b as r,k as i,m as a,v as o,y as s}from"./app-Xgp6P-Ux.js";import{t as c}from"./plugin-vue_export-helper-BDNMzG2s.js";var l=JSON.parse(`{"path":"/column/Python-Programming-Course/P08-research-ability/00-Why-do-you-need-to-have-research-skills.html","title":"00-你为什么要具备研究能力?","lang":"zh-CN","frontmatter":{"title":"00-你为什么要具备研究能力?","icon":"siwei1","date":"2025-02-23T22:23:44.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"你好，我是悦创。 我算是一个跨界学习的高手，也是一个具备较强研究能力的人。你可能会认为研究跟学习没什么区别，那我先要为你明确：学习是为了求一个高度，而研究是为了求一个广度。举个例子，在我看来学习就像登山，研究是探险，这个“险”就是对你来讲新的事物。 不客气地讲，很多熟悉我的人都讲：AI悦创这个人给人印象最深刻的就是他的研究能力，他能在很短的时间里就把一...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"00-你为什么要具备研究能力?\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2025-02-23T22:23:44.000Z\\",\\"dateModified\\":\\"2025-10-15T14:03:22.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/column/Python-Programming-Course/P08-research-ability/00-Why-do-you-need-to-have-research-skills.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"00-你为什么要具备研究能力?"}],["meta",{"property":"og:description","content":"你好，我是悦创。 我算是一个跨界学习的高手，也是一个具备较强研究能力的人。你可能会认为研究跟学习没什么区别，那我先要为你明确：学习是为了求一个高度，而研究是为了求一个广度。举个例子，在我看来学习就像登山，研究是探险，这个“险”就是对你来讲新的事物。 不客气地讲，很多熟悉我的人都讲：AI悦创这个人给人印象最深刻的就是他的研究能力，他能在很短的时间里就把一..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-10-15T14:03:22.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2025-02-23T22:23:44.000Z"}],["meta",{"property":"article:modified_time","content":"2025-10-15T14:03:22.000Z"}]]},"git":{"createdTime":1740321521000,"updatedTime":1760537002000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":17,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"42818473322eb48cbbb48755380fd811e8b8cdf6","time":1760537002000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 统一研究能力章节的图标为siwei1"},{"hash":"545c0fbf3a1b371119490c0c3cbeaa6a729e80e5","time":1748781177000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新"},{"hash":"6f390ce371904c5d13812b7ec2a9f826980e1492","time":1748781014000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add initial draft of \\"Three Essential Types of Awareness for Research\\" article"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"36a1379ae2fc7b11bc5aac4324d0b495906fd8de","time":1747266320000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修正“研究能力”章节中的语句，使其更加一致和流畅"},{"hash":"b9a74c448547d11a48159511b39c0f825f6b92e3","time":1747223269000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"优化“研究能力”章节内容，调整语句以增强逻辑性和流畅性"},{"hash":"06ebc1e4e5c1eb8530cfa98fed482b413dcbdd70","time":1747187494000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修正FAQ03.md和研究能力文档中的语句，使其更加清晰流畅"},{"hash":"50c493a7bc6b5cfd772f5b696c91e6e88a857055","time":1747119647000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修正文本中的格式和标点，使内容更加清晰流畅"},{"hash":"4fb0ce7166d75e1ce4bf2157061569bc40b7860a","time":1747118927000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修正文本中的标点和格式，使内容更加清晰流畅"},{"hash":"38bae5b21244af16c3cc5df33838ed8ee972c0ff","time":1747117937000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add initial draft of \\"Three Essential Types of Awareness for Research\\" article"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"90b1354a53c8ce5e577c9af40121db9dd2f9aa1d","time":1740667316000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文档，修正关于研究能力的描述，增强内容的准确性与逻辑性；新增关于研究本质及研究与学习区别的内容，提升读者的理解深度"},{"hash":"6a229118554429628fef40537ebcbfe4f430e8e0","time":1740494112000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文档，修正链接并添加新内容，删除不必要的图片，增强内容结构与可读性"},{"hash":"375e9f985e0942c3abebf77b19814cfd24169863","time":1740322988000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文档，新增关于研究必备三种意识的内容，提升内容清晰度与实用性"},{"hash":"7d83645e03e4efb51533c18c19f51ccf0093e707","time":1740322672000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文档，增加关于研究能力的定义及其重要性的详细说明，提升内容清晰度与实用性"},{"hash":"586ee436f161c0d628357ec93d8f9772777ccb7e","time":1740321521000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文档，新增关于研究能力的重要性及其课程内容，提升内容清晰度与实用性"}]},"readingTime":{"minutes":8.99,"words":2697},"filePathRelative":"column/Python-Programming-Course/P08-research-ability/00-Why-do-you-need-to-have-research-skills.md","excerpt":"<figure><figcaption></figcaption></figure>\\n<p>你好，我是悦创。</p>\\n<p>我算是一个跨界学习的高手，也是一个具备较强研究能力的人。你可能会认为研究跟学习没什么区别，那我先要为你明确：<strong>学习是为了求一个高度，而研究是为了求一个广度</strong>。举个例子，在我看来学习就像登山，研究是探险，这个“险”就是对你来讲新的事物。</p>\\n<p>不客气地讲，很多熟悉我的人都讲：AI悦创这个人给人印象最深刻的就是他的研究能力，他能在很短的时间里就把一样对他来讲全新的事物研究得能出来给人讲课了——这种能力就是我要在接下来的文章中要为你提供训练的能力。</p>","autoDesc":true}`),u={name:`00-Why-do-you-need-to-have-research-skills.md`};function d(c,l,u,d,f,p){let m=t(`Tabs`);return i(),n(`div`,null,[l[12]||=o(`<figure><img src="/assets/201807181537454271872409-D_O5zUaX.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你好，我是悦创。</p><p>我算是一个跨界学习的高手，也是一个具备较强研究能力的人。你可能会认为研究跟学习没什么区别，那我先要为你明确：<strong>学习是为了求一个高度，而研究是为了求一个广度</strong>。举个例子，在我看来学习就像登山，研究是探险，这个“险”就是对你来讲新的事物。</p><p>不客气地讲，很多熟悉我的人都讲：AI悦创这个人给人印象最深刻的就是他的研究能力，他能在很短的时间里就把一样对他来讲全新的事物研究得能出来给人讲课了——这种能力就是我要在接下来的文章中要为你提供训练的能力。</p><p>在带你训练你的研究能力之前，我先给<strong>研究能力</strong>下一个更精准的定义。 <strong>研究能力是一种主动的探究能力</strong> ，用英文讲就是“actively making meaning，rather than just absorbing information”。它包含两层意思：</p><ol><li>在学习的时候为了学得更好，而主动进入的对你自身来讲创造性的探究；</li><li>研究不是单纯地吸收信息。</li></ol><p>研究和学习的根本区别在于：学习最核心的部分是重复练习，而研究不是练习，更没有重复，只有不断地获得新东西。——<strong>所以研究是具有艺术性的</strong>。</p><p>这门课所说的研究能力，指的是：适用于每一个人的研究能力，是那些人人都应该掌握的研究能力。 <strong>其中最关键的一点，就是面对一个新事物、新课题的时候能够快速上手，并掌握概况的能力。</strong></p><p>在这个定义里，其实还隐含了一个没有点出来的关键词，就是<strong>跨界</strong>。如果一个人能跨界，在多个技能方面都有一定程度的掌握，那么毫无疑问他也是有研究能力的。我自己就是这样一个人。我在 PPT 制作、编程教学、跆拳道黑带、摄影、烹饪、运营、掌握多个大型软件的使用这些领域都做出了一些成绩。这些成绩的体现就是针对以上这些技能，我都出了教程、文章，我的研究能力算是很强的。</p><p><strong>那么一个人具备研究能力到底有什么好处呢？</strong></p><ul><li><p>首先，如果你想把你的专业学得跟大部分人差不多，那你只要有学习能力就可以了。而如果你想把你的专业学得比大部分人好，你肯定需要具备研究能力。</p></li><li><p>其次，有了研究能力，你在换工作、换环境的时候可以更好地适应，更好地进入状态，也更容易做出短平快的决策。</p></li><li><p>你可能觉得不换工作，不换环境就能逃过这一劫。但是我告诉你，这个时代变化这么快，想要在新世界和新机会面前表现得从容不迫，你不可以没有研究能力。</p></li></ul><p>我在这个部分，准备了五篇文章来与你探讨。</p><ul><li><p><strong>第一篇：我会告诉你研究的本质，以及在做研究的时候应该唤醒的三种意识</strong>。 缺乏这三种重要的意识，也许是你不具备研究能力最大的可能性的所在。</p></li><li><p><strong>第二篇：我会告诉你，搜集研究资料，你要做到一个精准的平衡，足量而要节制</strong>。 你无法做出有效的研究，可能是你的研究资料远远没有达到足量。同时你无法做到有效的研究也可能是你面对研究资料缺乏克制。</p></li><li><p><strong>第三篇：你会学到怎么用批判性思维来处理搜集到的信息</strong>。</p></li><li><p><strong>第四篇：当你做了一番研究之后，基本有了研究结论了，我们来谈一谈怎么把研究结论成果化</strong>。</p></li><li><p><strong>第五篇：有心从事学术研究的同学们才需要阅读这一节，这一节主要是讲如果你要写一篇学术性论文</strong>。 我从我对西方学术体系的认识以及获得的经验里，给你提供一些有效的建议。</p></li></ul><p>最后我要提醒你，还记得研究能力的定义吗？研究能力是一种主动的探究能力，所以<strong>研究不是被动地吸收</strong>。不是听别人为你讲，而是主动进入的一种状态。</p><p>这五篇文章最重要的价值就是尝试培养你自己的研究能力，而不总是听别人告诉你心得体会，所以你必须要在这次的阅读中收获提升研究能力的技术手段，掌握了研究的套路之后亲自去实践。</p><p>接下来请跟我一起进入到正式的课程内容，将自己的研究能力提升起来吧。</p>`,16),r(m,{data:[{id:`c1`},{id:`c2🌟`},{id:`c3`},{id:`c4`},{id:`c5`},{id:`c6`}]},{title0:e(({value:e,isActive:t})=>[...l[0]||=[s(`c1`,-1)]]),title1:e(({value:e,isActive:t})=>[...l[1]||=[s(`c2🌟`,-1)]]),title2:e(({value:e,isActive:t})=>[...l[2]||=[s(`c3`,-1)]]),title3:e(({value:e,isActive:t})=>[...l[3]||=[s(`c4`,-1)]]),title4:e(({value:e,isActive:t})=>[...l[4]||=[s(`c5`,-1)]]),title5:e(({value:e,isActive:t})=>[...l[5]||=[s(`c6`,-1)]]),tab0:e(({value:e,isActive:t})=>[...l[6]||=[a(`p`,null,`学习是驾校，研究是自驾探险`,-1),a(`blockquote`,null,[a(`p`,null,`嚯，你这个比喻，很容易出事故啊 …`)],-1)]]),tab1:e(({value:e,isActive:t})=>[...l[7]||=[a(`p`,null,`试听之前：研究，跟我这样的渣有什么关系？`,-1),a(`p`,null,`试听之后：①英文说的真好！②我被悦创大神彻底说服力`,-1),a(`blockquote`,null,[a(`p`,null,`任何人都需要做研究。`),a(`p`,null,`注意，做研究不一定是搞科研。你买一样东西之前有没有做研究呢？买东西之前不做研究，你很容易买到让自己后悔的东西。就连买菜，你不做研究，你都买不到新鲜的，被人坑，被人骗。人们在购买昂贵的东西时，往往更会去做研究。比如买一辆车，买一件乐器或者是买一台咖啡机。任何一个要买车的人，可能都会去互联网上搜索自己感兴趣的车型，这对应的就是从互联网搜索引擎开始，然后会去视频网站上看一些宣传视频，试驾视频，功能讲解视频和评测视频，接着就会钻进汽车论坛里一个帖子一个帖子地浏览而久久不能自拔，恭喜你，这时候你已经进入到良好的研究状态了。`),a(`p`,null,`当你有了一些相对确定的选择之后，你就会接二连三地跑到各个 4S 店进行现场观摩，亲自试驾，这对应的就是执行和实践，过程中你可能不需要写作，但你会基于体验去思考。最后你试来试去还是拿不定主意，你去找懂车的高手探讨，跟行家请教。`)],-1)]]),tab2:e(({value:e,isActive:t})=>[...l[8]||=[a(`p`,null,`大部分人研究学习一件事情，很容易就略懂一二，但如果要进入深度思考，却很难。一个全新的领域，特别是需要实践的一个领域，能跳过实践的积累做到快速精通吗？`,-1),a(`blockquote`,null,[a(`p`,null,`你所说的「实践」已经脱离研究的部分了。研究不需要实践，实践是练习。或者你的意思是类似做试验的那种「试错」？`)],-1)]]),tab3:e(({value:e,isActive:t})=>[...l[9]||=[a(`p`,null,`秒定啊～好奇宝宝就是愿意东学学西学学。就乐意听您的～`,-1),a(`blockquote`,null,[a(`p`,null,`「好奇宝宝」有十足的研究驱动力，要是再能将资料收集做到足量而节制，有批判性思维，并能够不断输出研究结论，那你无疑是一个有研究能力的人。`)],-1)]]),tab4:e(({value:e,isActive:t})=>[...l[10]||=[a(`p`,null,[s(`什么是研究能力？为什么需要它（好处）？套路是什么？`),a(`br`),s(` 答：主动探究。为了更好地应对竞争和适应变化。唤起好奇心，足量而节制的收集资料，批判性的处理，结论成果化。`)],-1),a(`blockquote`,null,[a(`p`,null,`我天呐，你是善于总结的高手。强烈建议你在「得到」出一个「如何成为总结的高手」精品课。`)],-1)]]),tab5:e(({value:e,isActive:t})=>[...l[11]||=[a(`p`,null,[s(`搜集资料是在网上搜集还是怎么？很多想学的东西苦于没有方法以及有效地利用时间的思维，希望老师给出建议，谢谢`),a(`em`,null,`🙏`),s(`。`)],-1),a(`blockquote`,null,[a(`p`,null,`如果你的研究仅限于解决一些日常工作和生活中的问题，或者就是想研究研究买哪个牌子的商品最适合自己，那你没有必要进入图书馆。但是如果你想做的是具有学术性的研究，那你就一定要去图书馆了。因为学术要求系统性，信息量，和文本支持。这三点只有互联网上的信息是不能满足的。`),a(`hr`),a(`p`,null,`对于一般的研究，你可以先从互联网搜索开始；但对于学术研究，你应该先钻进图书馆，当图书馆的资料，不足以支撑你学术研究的系统性和信息量时，你可以进一步地在互联网上获得学术信息。这里有一个先后顺序，因为对于学术研究来说，从图书馆获得信息量与文本支持，和从互联网获得信息量与文本支持，它们之间有三点差异。`),a(`hr`),a(`ul`,null,[a(`li`,null,[a(`p`,null,`第一，从互联网获得信息更快、更新。这是显而易见的。但这不是互联网相对图书馆的压倒性优势。我们要考虑一个问题，为什么那么多图书馆在今天还依然存在着，没有被互联网获取信息的便捷全面取代。`)]),a(`li`,null,[a(`p`,null,`第二，从图书馆获得信息更可靠。图书馆里收藏的都是正式的出版物，正式的出版物一定是相对更可靠的。互联网上的那些言论，就算是做学术探讨，讲求的也是一个时效性，而时效性的另一面就是缺乏推敲以及时间的检验。`)]),a(`li`,null,[a(`p`,null,`第三，如果是做学术研究，互联网上的信息量与文本支持其实相对更少。国外有个问答网站叫 Quora ，它的创始人 Adam D' Angelo 声称，「大部分人类的知识尚未出现在互联网上，可能以经验的形式存储在民间，或存储在只有专家能读懂的学术论文中 … 」你看，只有专家能读懂的学术论文恰恰是你要做学术研究要去读的，而它们不在互联网上，都在图书馆里。所以我说，你要是做学术研究的话，互联网能提供给你的有价值的信息其实是十分有限的。`)])])],-1)]]),_:1})])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};